whiteboard:
@startuml
title Nano-vLLM 项目目录结构与模块职责

skinparam packageStyle rectangle
skinparam componentStyle rectangle

package "入口层 (Entry)" as Entry {
  [llm.py\nLLM类, 仅5行\n用户API入口] as LLM
  [llm_engine.py\nLLMEngine, 90行\n引擎编排器] as LLME
}

package "引擎核心层 (Engine Core)" as Core {
  [scheduler.py\nScheduler, 92行\n请求调度+连续批处理] as SCH
  [block_manager.py\nBlockManager, 120行\nPagedAttention内存管理\n+前缀缓存] as BM
  [model_runner.py\nModelRunner, 257行\n推理执行引擎\n+CUDA Graph] as MR
  [sequence.py\nSequence, 83行\n请求序列抽象\n状态机+块映射] as SEQ
}

package "模型层 (Model Layers)" as Model {
  [qwen3.py\nQwen3ForCausalLM\n216行, 完整Transformer] as Q3
  [attention.py\nFlashAttention+Triton\n75行, KV Cache存取] as ATTN
  [linear.py\n5种并行线性层\n156行, QKV合并+TP] as LIN
  [rotary_embedding.py\nRoPE, 59行\ncos/sin缓存+编译] as ROPE
  [layernorm.py\nRMSNorm, 50行\n融合residual_add] as NORM
  [sampler.py\nSampler, 12行\nGumbel-Max采样] as SMP
  [embed_head.py\nEmbed+LM Head, 66行\n词表并行] as EMB
  [activation.py\nSiluAndMul, 11行\nSwiGLU融合] as ACT
}

package "工具层 (Utils)" as Util {
  [context.py\nContext, 27行\n全局上下文传递] as CTX
  [loader.py\n权重加载, 28行\nsafetensors+融合] as LOAD
}

package "配置 (Config)" as Cfg {
  [config.py\nConfig, 25行\n数据中心配置类] as CFG
  [sampling_params.py\nSamplingParams\n11行, 采样参数] as SP
}

Entry --> Core
Core --> Model
Model --> Util
Entry --> Cfg
Core --> Cfg

@enduml
